import{api,SUPABASE_URL,PUBLISHABLE_KEY,money,esc,messageStatus}from'/config.mjs';
const $=s=>document.querySelector(s),app=$('#admin-app'),KEY='hocco-message-team-session';
let session=null,data=null,filter='all',timer;
try{session=JSON.parse(localStorage.getItem(KEY))}catch{}
const toast=t=>{$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4500)};
const badge=o=>`<span class="badge ${o.review==='rejected'?'red':o.delivery==='published'?'success':'orange'}">${esc(messageStatus(o))}</span>`;
const localDateTime=value=>{if(!value)return'';const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
function modal(html,onSubmit){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<button type="button" class="close" aria-label="Fechar" style="float:right">×</button>${html}`;document.body.append(d);d.querySelector('.close').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.querySelector('form')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');if(b)b.disabled=true;try{await onSubmit(new FormData(e.target),d)}catch(error){d.querySelector('[role=alert]').textContent=error.message;if(b)b.disabled=false}});d.showModal();return d}
async function auth(path,body){const r=await fetch(SUPABASE_URL+'/auth/v1/'+path,{method:'POST',headers:{apikey:PUBLISHABLE_KEY,'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error('Não foi possível entrar. Confira os dados da conta autorizada.');if(!d.expires_at)d.expires_at=Math.floor(Date.now()/1000)+(d.expires_in||3600);return d}
async function accessToken(){if(!session?.access_token)throw Error('Entre com sua conta da equipe.');if(session.expires_at*1000<Date.now()+60000){session=await auth('token?grant_type=refresh_token',{refresh_token:session.refresh_token});localStorage.setItem(KEY,JSON.stringify(session))}return session.access_token}
async function call(action,body){try{return await api(action,body,await accessToken())}catch(e){if(e.status===401||e.status===403){session=null;localStorage.removeItem(KEY);renderLogin(e.message)}throw e}}
function renderLogin(error=''){data=null;$('#session-actions').innerHTML='';app.innerHTML=`<section class="narrow admin-login"><div class="eyebrow">Equipe HOCCO</div><h1 class="section-title">O cuidado acontece<br><em>nos bastidores.</em></h1><p class="subheading">Área própria do Hocco Message. Entre com a conta administradora já cadastrada na HOCCO. Não há cadastro público nem acesso de clientes.</p><form id="login"><div class="field"><label for="email">E-mail da equipe</label><input id="email" name="email" type="email" autocomplete="username" value="sandroempresa.sp@gmail.com" required></div><div class="field"><label for="password">Senha</label><input id="password" name="password" type="password" autocomplete="current-password" required></div><button class="btn purple full" id="login-button">Entrar no controle →</button><div role="alert" class="error" id="login-error">${esc(error)}</div></form><p class="hint">O acesso depende de uma conta válida e de permissão ativa para este produto. Conhecer o endereço não libera o painel.</p></section>`;$('#login').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=$('#login-button');b.disabled=true;b.textContent='Validando acesso…';try{session=await auth('token?grant_type=password',{email:f.get('email').trim(),password:f.get('password')});localStorage.setItem(KEY,JSON.stringify(session));await load()}catch(error){session=null;localStorage.removeItem(KEY);renderLogin(error.message)}}}
async function load(){if(!session)return renderLogin();app.innerHTML='<div class="empty">Validando a conta e carregando o controle…</div>';try{data=await call('admin.dashboard',{});render()}catch(e){if(session)renderLogin(e.message)}}
const ready=o=>o.review==='approved'&&o.payment==='confirmed'&&o.delivery==='waiting';
function renderSponsors(){const q=data.sponsorSettings||{price_cents:2990,capacity:50,enabled:true},rows=data.sponsors||[];$('#session-actions').innerHTML='<button class="btn secondary small" id="sponsor-back">Mensagens</button> <button class="btn secondary small" id="sponsor-trash">Lixeira</button> <button class="btn secondary small" id="refresh">Atualizar</button> <button class="btn ghost small" id="logout">Sair</button>';$('#refresh').onclick=load;$('#sponsor-back').onclick=()=>{filter='all';render()};$('#sponsor-trash').onclick=()=>{filter='trash';render()};$('#logout').onclick=()=>{session=null;localStorage.removeItem(KEY);renderLogin()};app.innerHTML='<div class="admin-top"><div><div class="eyebrow">Equipe HOCCO · Ir Além</div><h1 class="section-title">Patrocinadores<br><em>em curadoria.</em></h1><p class="subheading">Até 50 empresas diferentes. Cada pagamento confirma uma semana, sem renovação automática.</p></div><span class="badge">'+rows.filter(x=>x.review==='pending').length+' pendentes de curadoria</span></div><div class="metrics"><div class="metric"><b>'+rows.filter(x=>x.review==='pending').length+'</b><span>Novas solicitações</span></div><div class="metric"><b>'+rows.filter(x=>x.review==='approved'&&x.payment==='pending').length+'</b><span>Aguardando PIX</span></div><div class="metric"><b>'+rows.filter(x=>x.expires_at&&Date.parse(x.expires_at)>Date.now()).length+'</b><span>Semanas ativas</span></div><div class="metric"><b>'+money(rows.filter(x=>x.payment==='confirmed').reduce((n,x)=>n+x.price_cents,0))+'</b><span>Recebido</span></div></div><div class="admin-grid"><section><div class="orders">'+(rows.length?rows.map(x=>'<article class="order"><div class="sponsor-review-head"><img class="sponsor-review-logo" src="'+esc(x.logo_url)+'" alt="Logo de '+esc(x.company_name)+'" loading="lazy" referrerpolicy="no-referrer" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><div class="sponsor-logo-fallback" hidden aria-label="Logo indisponível">'+esc(x.company_name.slice(0,1).toUpperCase())+'</div><div class="sponsor-review-title"><strong>'+esc(x.company_name)+'</strong><span class="badge '+(x.review==='rejected'?'red':x.review==='approved'?'success':'orange')+'">'+(x.review==='pending'?'Em curadoria':x.review==='approved'?'Aprovado':'Recusado')+'</span></div></div><div class="sponsor-admin-cover"><img src="'+esc(x.cover_url||x.logo_url)+'" alt="Capa enviada por '+esc(x.company_name)+'" loading="lazy" referrerpolicy="no-referrer"></div><div class="sponsor-admin-description"><b>Descrição que ficará no perfil público</b><br>'+esc(x.company_description||'Descrição ainda não informada.')+'</div><p class="admin-social"><b>Categoria:</b> '+esc(x.category||'Outros')+'</p><p class="admin-social"><b>CNPJ:</b> '+esc(x.cnpj||'não informado')+' · <b>Razão social:</b> '+esc(x.legal_name||'não informada')+'</p><p class="admin-social"><b>Contato:</b> '+esc(x.contact_name)+' · <a href="mailto:'+esc(x.email)+'">'+esc(x.email)+'</a></p><p class="admin-social"><b>WhatsApp:</b> '+(x.phone?esc(x.phone):'não informado')+'</p><p class="admin-social"><b>Destino:</b> <a href="'+esc(x.destination_url)+'" target="_blank" rel="noopener noreferrer">'+esc(x.destination_url)+' ↗</a></p>'+(x.community_offer?'<p class="admin-social"><b>Oferta à comunidade:</b> '+esc(x.community_offer)+'</p>':'')+'<p class="admin-social"><a href="'+esc(x.logo_url)+'" target="_blank" rel="noopener noreferrer">Abrir logo em tamanho original ↗</a></p><div class="meta"><b>Pedido:</b> '+esc(x.code)+' · <b>Valor:</b> '+money(x.price_cents)+' · <b>Pagamento:</b> '+esc(x.payment)+(x.payment_claimed?' · cliente informou PIX':'')+'</div><div class="meta"><b>WhatsApp:</b> agradecimentos '+(x.thank_you_opt_in?'autorizados':'não autorizados')+' · aviso de encerramento '+(x.expiry_notice_opt_in?'autorizado':'não autorizado')+'</div><div class="meta"><b>Solicitado em:</b> '+esc(x.created_at?new Date(x.created_at).toLocaleString('pt-BR'):'data indisponível')+(x.expires_at?' · <b>Semana:</b> '+esc(new Date(x.starts_at).toLocaleString('pt-BR'))+' até '+esc(new Date(x.expires_at).toLocaleString('pt-BR')):'')+'</div>'+(x.reason?'<div class="note">Motivo: '+esc(x.reason)+'</div>':'')+'<div class="actions">'+(x.review==='pending'?'<button class="btn secondary small" data-sponsor-action="approve" data-id="'+x.id+'">Aprovar</button><button class="btn danger small" data-sponsor-action="reject" data-id="'+x.id+'">Recusar</button>':'')+(x.review==='approved'&&x.payment==='pending'?'<button class="btn small" data-sponsor-action="pay" data-id="'+x.id+'">Confirmar PIX e iniciar 7 dias</button>':'')+'<button class="btn danger small" data-delete-sponsor="'+x.id+'">Excluir definitivamente</button>'+'</div></article>').join(''):'<div class="empty"><h3>Nenhuma empresa ainda.</h3><p>Quando alguém enviar o pedido, ele aparecerá aqui.</p></div>')+'</div></section><aside class="settings"><h3>Preço semanal do patrocínio</h3><p class="side-note">Ajuste o valor. A capacidade máxima fica em 50 marcas diferentes.</p><form id="sponsor-price-form"><div class="field"><label for="sponsor-price">Valor de 7 dias · R$</label><input id="sponsor-price" name="price" type="number" min="1" max="9999.99" step="0.01" value="'+(q.price_cents/100).toFixed(2)+'" required></div><div class="field"><label>Vagas simultâneas</label><input value="50 empresas" readonly></div><label class="check"><input name="enabled" type="checkbox" '+(q.enabled!==false?'checked':'')+'><span>Receber novas inscrições de patrocinadores</span></label><p class="side-note">Período de 7 dias corridos, iniciado na confirmação do PIX. Sem recorrência.</p><button class="btn purple full">Salvar preço</button><div id="sponsor-error" class="error" role="alert"></div></form></aside></div>';document.querySelectorAll('[data-sponsor-action]').forEach(b=>b.onclick=async()=>{const row=rows.find(x=>x.id===b.dataset.id),op=b.dataset.sponsorAction;let payload={};if(op==='reject'){const reason=prompt('Informe um motivo claro para a recusa:');if(!reason)return;payload.reason=reason}if(op==='pay'&&!confirm('Conferiu no extrato o PIX de '+money(row.price_cents)+'? A confirmação inicia a semana de 7 dias.'))return;b.disabled=true;try{await call('admin.sponsor.mutate',{id:row.id,operation:op,payload});await load();toast('Patrocínio atualizado.')}catch(e){toast(e.message);b.disabled=false}});document.querySelectorAll('[data-delete-sponsor]').forEach(b=>b.onclick=async()=>{const row=rows.find(x=>x.id===b.dataset.deleteSponsor);if(!row)return;const typed=prompt('Exclusão permanente: digite exatamente o nome da empresa para confirmar.\n\n'+row.company_name);if(typed!==row.company_name)return;b.disabled=true;try{await call('admin.sponsor.delete',{id:row.id,confirmName:typed});await load();toast('Empresa removida definitivamente.')}catch(e){toast(e.message);b.disabled=false}});$('#sponsor-price-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await call('admin.sponsor.settings',{payload:{priceCents:Math.round(Number(new FormData(e.target).get('price'))*100),capacity:50,enabled:new FormData(e.target).has('enabled')}});await load();toast('Preço semanal atualizado.')}catch(e){$('#sponsor-error').textContent=e.message;b.disabled=false}}}
function renderTrash(){const orders=data.trashOrders||[],sponsors=data.trashSponsors||[];$('#session-actions').innerHTML='<button class="btn secondary small" id="trash-back">Mensagens</button> <button class="btn secondary small" id="trash-refresh">Atualizar</button> <button class="btn ghost small" id="trash-logout">Sair</button>';app.innerHTML='<div class="admin-top"><div><div class="eyebrow">Equipe HOCCO · registros preservados</div><h1 class="section-title">Lixeira<br><em>recuperável.</em></h1><p class="subheading">Os registros arquivados saem das filas e da área pública. Restaurar mantém o histórico. Arquivar não apaga os dados nem reduz o armazenamento.</p></div><span class="badge">'+(orders.length+sponsors.length)+' registros</span></div><div class="orders">'+(orders.map(o=>'<article class="order"><div class="row wrap"><strong>'+esc(o.name)+'</strong>'+badge(o)+'</div><p class="admin-message">| @'+esc(o.social_handle||'')+' · '+esc(o.message)+'</p><div class="meta">Pedido '+esc(o.code)+' · arquivado em '+esc(new Date(o.archived_at).toLocaleString('pt-BR'))+'</div><div class="actions"><button class="btn secondary small" data-restore-type="order" data-id="'+o.id+'">Restaurar pedido</button></div></article>').join(''))+(sponsors.map(x=>'<article class="order"><div class="sponsor-review-head"><img class="sponsor-review-logo" src="'+esc(x.logo_url)+'" alt="Logo de '+esc(x.company_name)+'" loading="lazy"><strong>'+esc(x.company_name)+'</strong></div><div class="meta">Patrocínio '+esc(x.code)+' · '+esc(x.payment)+' · arquivado em '+esc(new Date(x.archived_at).toLocaleString('pt-BR'))+'</div><div class="actions"><button class="btn secondary small" data-restore-type="sponsor" data-id="'+x.id+'">Restaurar patrocinador</button></div></article>').join(''))+(!orders.length&&!sponsors.length?'<div class="empty"><h3>A lixeira está vazia.</h3><p>Quando você arquivar registros, poderá restaurá-los aqui.</p></div>':'')+'</div>';$('#trash-back').onclick=()=>{filter='all';render()};$('#trash-refresh').onclick=load;$('#trash-logout').onclick=()=>{session=null;localStorage.removeItem(KEY);renderLogin()};document.querySelectorAll('[data-restore-type]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await call('admin.records.restore',{type:b.dataset.restoreType,id:b.dataset.id});await load();filter='trash';render();toast('Registro restaurado.')}catch(e){b.disabled=false;toast(e.message)}})}
function communityAvatar(index){const i=Math.max(0,Math.min(19,Number(index||1)-1)),x=i%5*25,y=Math.floor(i/5)*100/3;return `<span class="community-admin-avatar" aria-hidden="true" style="background-position:${x}% ${y}%"></span>`}
function renderCommunity(){
 const rows=data.communityMessages||[],pending=rows.filter(x=>x.review==='pending').length,payments=rows.filter(x=>x.payment==='pending').length,visible=rows.filter(x=>x.destination!=='live'&&x.published_at&&Date.parse(x.expires_at)>Date.now()).length,queued=rows.filter(x=>x.destination==='live'&&x.live_status==='queued'&&x.review==='approved'&&x.payment==='confirmed').length;
 $('#session-actions').innerHTML='<button class="btn secondary small" id="community-back">Mensagens</button> <button class="btn secondary small" id="community-refresh">Atualizar</button> <button class="btn ghost small" id="community-logout">Sair</button>';
 $('#community-back').onclick=()=>{filter='all';render()};$('#community-refresh').onclick=load;$('#community-logout').onclick=()=>{session=null;localStorage.removeItem(KEY);renderLogin()};
 app.innerHTML=`<div class="admin-top"><div><div class="eyebrow">Equipe HOCCO · curadoria</div><h1 class="section-title">Comunidade<br><em>e LIVE.</em></h1><p class="subheading">A Comunidade é publicada automaticamente por 3 horas após pagamento e aprovação. As mensagens para LIVE entram na fila após essas confirmações.</p></div><span class="badge success">Acesso autenticado</span></div><div class="metrics"><div class="metric"><b>${pending}</b><span>Em curadoria</span></div><div class="metric"><b>${payments}</b><span>Aguardando pagamento</span></div><div class="metric"><b>${visible}</b><span>Visíveis na Comunidade</span></div><div class="metric"><b>${queued}</b><span>Na fila da LIVE</span></div></div><div class="orders community-admin-list">${rows.length?rows.map(o=>{const isLive=o.destination==='live',active=!isLive&&o.published_at&&Date.parse(o.expires_at)>Date.now(),status=o.review==='rejected'?'Recusada':isLive&&o.live_status==='read'?'Leitura registrada na LIVE':isLive&&o.live_status==='queued'?'Na fila da próxima LIVE':active?'Visível na Comunidade':o.review==='approved'&&o.payment==='confirmed'?'Confirmada':o.payment==='confirmed'&&o.review==='pending'?'Pago · revisão adicional':o.payment==='pending'&&o.payment_claimed?'Pagamento informado · conferir':o.review==='approved'?'Aprovada · aguardando pagamento':'Em curadoria';return `<article class="order community-admin-card ${isLive?'live-admin-card':''}"><div class="community-admin-identity">${communityAvatar(o.avatar_index)}<div><strong>${esc(o.member_name)}</strong><span>@${esc(o.member_username)}</span></div><span class="badge ${o.review==='rejected'?'red':active||o.live_status==='queued'?'success':'orange'}">${status}</span></div><p class="admin-message community-admin-message">${esc(o.message)}</p><div class="meta"><b>${isLive?'Destino: próxima LIVE':'Destino: Comunidade'}</b> · ${money(o.price_cents)} · ${esc(o.code)} · ${new Date(o.created_at).toLocaleString('pt-BR')}</div>${o.payment_claimed&&o.payment==='pending'?'<div class="note" style="margin-top:10px">O cliente informou que pagou. Confira no extrato.</div>':''}${o.reason?`<div class="note" style="margin-top:10px">Motivo: ${esc(o.reason)}</div>`:''}${o.published_at?`<div class="meta">${active?'Visível até':'Expirou em'} ${new Date(o.expires_at).toLocaleString('pt-BR')}</div>`:''}<div class="actions">${o.review==='pending'?`<button class="btn secondary small" data-community-action="approve" data-id="${o.id}">Aprovar mensagem</button><button class="btn danger small" data-community-action="reject" data-id="${o.id}">Recusar com motivo</button>`:''}${o.payment==='pending'&&o.review!=='rejected'?`<button class="btn secondary small" data-community-action="pay" data-id="${o.id}">Registrar pagamento manual</button>`:''}${isLive&&o.live_status==='queued'?`<button class="btn small" data-community-action="live_read" data-id="${o.id}">Registrar leitura na LIVE</button>`:''}${o.review==='rejected'&&o.payment==='confirmed'?`<button class="btn danger small" data-community-action="refund" data-id="${o.id}">Registrar devolução</button>`:''}${active?'<span class="badge success">No carrossel da Comunidade</span>':''}</div></article>`}).join(''):'<div class="empty"><h3>Nenhuma mensagem ainda.</h3><p>Mensagens da Comunidade e da LIVE aparecerão aqui.</p></div>'}</div>`;
 document.querySelectorAll('[data-community-action]').forEach(button=>button.onclick=()=>communityAction(rows.find(x=>x.id===button.dataset.id),button.dataset.communityAction))
}
function communityAction(post,operation){if(!post)return;const labels={approve:'Aprovar mensagem',pay:'Confirmar recebimento do Pix',reject:'Recusar mensagem',refund:'Registrar devolução',live_read:'Registrar leitura na LIVE'};if(operation==='live_read'){if(!confirm('Confirma que esta mensagem foi lida na LIVE?'))return;call('admin.community.mutate',{id:post.id,operation}).then(()=>load()).then(()=>toast('Leitura registrada.')).catch(e=>toast(e.message));return}if(operation==='reject'){modal(`<h2>Recusar mensagem</h2><p class="subheading">Informe o motivo específico. Se o Pix já foi recebido, registre a devolução após realizá-la.</p><form><div class="field"><label for="community-reason">Motivo</label><textarea id="community-reason" name="reason" required maxlength="500"></textarea></div><div class="error" role="alert"></div><button class="btn danger full" type="submit">Confirmar recusa</button></form>`,async(f,d)=>{await call('admin.community.mutate',{id:post.id,operation,payload:{reason:f.get('reason').trim()}});d.close();await load();toast('Mensagem recusada.')});return}const body=operation==='approve'?'<p class="subheading">A equipe analisou o texto e confirma que ele segue as regras da Comunidade.</p><label class="check"><input type="checkbox" required><span>Conferi a mensagem e autorizo sua publicação quando o Pix também estiver confirmado.</span></label>':operation==='pay'?'<p class="subheading">Mensagem '+esc(post.code)+' · '+money(post.price_cents)+'. Este registro não movimenta dinheiro.</p><label class="check"><input type="checkbox" required><span>Conferi o recebimento de '+money(post.price_cents)+' no extrato bancário.</span></label>':'<p class="subheading">Este registro não movimenta dinheiro.</p><label class="check"><input type="checkbox" required><span>Confirmei a devolução de '+money(post.price_cents)+' ao cliente.</span></label>';modal(`<h2>${labels[operation]}</h2><form>${body}<div class="error" role="alert"></div><button class="btn purple full" type="submit">Confirmar registro</button></form>`,async(_,d)=>{await call('admin.community.mutate',{id:post.id,operation});d.close();await load();toast(operation==='pay'?'Recebimento do Pix registrado.':operation==='approve'?'Curadoria aprovada.': 'Devolução registrada.')})}
function render(){if(!data)return;if(filter==='trash')return renderTrash();if(filter==='sponsors')return renderSponsors();if(filter==='community')return renderCommunity();const s=data.settings;$('#session-actions').innerHTML='<button class="btn secondary small" id="refresh">Atualizar</button> <button class="btn ghost small" id="logout">Sair</button>';$('#refresh').onclick=load;$('#logout').onclick=async()=>{const old=session;session=null;localStorage.removeItem(KEY);renderLogin();if(old?.access_token)fetch(SUPABASE_URL+'/auth/v1/logout',{method:'POST',headers:{apikey:PUBLISHABLE_KEY,Authorization:'Bearer '+old.access_token}}).catch(()=>{})};const orders=data.orders.filter(o=>filter==='all'||filter==='review'&&o.review==='pending'||filter==='queue'&&ready(o)||filter==='refund'&&o.review==='rejected'&&o.payment==='confirmed'||filter==='published'&&o.delivery==='published');app.innerHTML=`<div class="admin-top"><div><div class="eyebrow">Hocco Message · equipe autorizada</div><h1 class="section-title">Cada recado,<br><em>bem cuidado.</em></h1><p class="subheading">Curadoria, pagamento, fila de edição e preço em um controle próprio.</p></div><span class="badge success">Acesso autenticado</span><button class="btn secondary small" id="community-tab">Comunidade</button> <button class="btn secondary small" id="sponsor-tab">Patrocinadores / Ir Além</button> <button class="btn secondary small" id="trash-tab">Lixeira</button></div><section class="daily-report" aria-labelledby="daily-report-title"><div class="daily-report-head"><div><div class="eyebrow">Controle · resumo operacional</div><h2 id="daily-report-title">Relatório diário</h2><small>${data.dailyReport?'Gerado em '+esc(new Date(data.dailyReport.generated_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})):'Disponível todos os dias às 23h59 · horário de Brasília'}</small></div>${data.dailyReport?'<span class="badge success">Último relatório</span>':'<span class="badge orange">Aguardando fechamento</span>'}</div>${data.dailyReport?`<p class="daily-report-summary">${esc(data.dailyReport.content?.summary||'Resumo operacional concluído.')}</p><div class="daily-report-metrics"><div><strong>${data.dailyReport.content?.visits?.total??0}</strong><span>Acessos</span></div><div><strong>${data.dailyReport.content?.orders?.created_today??0}</strong><span>Mensagens recebidas</span></div><div><strong>${data.dailyReport.content?.sponsors?.active??0}</strong><span>Patrocínios ativos</span></div><div><strong>${data.dailyReport.content?.events?.errors_today??0}</strong><span>Alertas de erro</span></div></div>`:'<p class="daily-report-summary">O relatório deste dia aparece aqui após a rotina automática das 23h59. O processamento ocorre em segundo plano.</p>'}<small class="daily-report-foot">Os dados são agregados e ficam visíveis somente para a equipe autenticada.</small></section><div class="note"><strong>Operação financeira.</strong> A equipe confere recebimentos e devoluções no extrato. Depois de registrar a veiculação, o aviso autorizado é enviado automaticamente pela API oficial do WhatsApp; falhas podem ser reenviadas nesta fila.</div><div class="actions" style="margin:16px 0"><button class="btn danger small" id="archive-all">Zerar filas e enviar para a lixeira</button><span class="hint">Arquiva pedidos e patrocínios; a restauração fica disponível na Lixeira.</span></div><div class="metrics"><div class="metric"><b>${data.orders.filter(o=>o.review==='pending').length}</b><span>Em curadoria</span></div><div class="metric"><b>${data.orders.filter(ready).length}</b><span>Prontas para edição</span></div><div class="metric"><b>${data.orders.filter(o=>o.delivery==='published').length}</b><span>Veiculações registradas</span></div><div class="metric"><b>${money(data.orders.filter(o=>o.payment==='confirmed').reduce((n,o)=>n+o.price_cents,0))}</b><span>Recebido</span></div></div><div class="admin-grid"><section><div class="filters">${[['all','Todas'],['review','Curadoria'],['queue','Fila de edição'],['refund','Devoluções'],['published','Veiculadas']].map(([v,l])=>`<button class="filter ${v===filter?'active':''}" data-filter="${v}">${l}</button>`).join('')}</div><div class="orders">${orders.length?orders.map(o=>`<article class="order"><div class="row wrap"><strong>${esc(o.name)}</strong>${badge(o)}</div><p class="admin-social">${esc(o.social_platform==='tiktok'?'TikTok':'Instagram')} · @${esc(o.social_handle||'')}</p><p class="admin-message">| @${esc(o.social_handle||'')} · ${esc(o.message)}</p><div class="meta">${esc(o.code)} · posição ${o.slot} · ${money(o.price_cents)} · ${esc(o.episode)}</div><div class="meta">Pagamento: ${esc(o.payment)}${o.payment_claimed?' · informado pelo cliente':''}</div><div class="meta">WhatsApp: ${o.whatsapp_opt_in||o.reminder_active?esc(o.phone)+(o.whatsapp_opt_in?(o.notification==='sent'?' · aviso enviado':o.notification==='failed'?' · aviso falhou':o.notification==='sending'?' · enviando aviso':' · aviso pendente'):''):'não autorizado'}</div><div class="meta">Lembretes da ofensiva: ${o.reminder_active?'autorizados · a cada 2 dias':'não autorizados'}</div>${o.reason?`<div class="note" style="margin-top:12px">Motivo: ${esc(o.reason)}</div>`:''}<div class="actions">${o.review==='pending'?`<button class="btn secondary small" data-action="approve" data-id="${o.id}">Aprovar mensagem</button>`:''}${o.review!=='rejected'&&o.delivery!=='published'?`<button class="btn danger small" data-action="reject" data-id="${o.id}">Reprovar com motivo</button>`:''}${o.payment==='pending'&&o.review!=='rejected'?`<button class="btn secondary small" data-action="pay" data-id="${o.id}">Confirmar recebimento</button>`:''}${ready(o)?`<button class="btn small" data-action="publish" data-id="${o.id}">Publicar no YouTube</button><button class="btn secondary small" data-action="copy" data-id="${o.id}">Copiar para edição</button>`:''}${o.review==='rejected'&&o.payment==='confirmed'?`<button class="btn danger small" data-action="refund" data-id="${o.id}">Registrar devolução</button>`:''}${o.delivery==='published'?`<a class="btn secondary small" href="${esc(o.video_url)}" target="_blank" rel="noopener noreferrer">Ver vídeo ↗</a>${o.whatsapp_opt_in&&['pending','failed'].includes(o.notification)?`<button class="btn secondary small" data-action="notice" data-id="${o.id}">${o.notification==='failed'?'Tentar WhatsApp novamente':'Enviar aviso'}</button>`:o.notification==='sent'?'<span class="badge success">Aviso enviado</span>':o.notification==='sending'?'<span class="badge">Enviando aviso…</span>':''}`:''}<button class="btn ghost small" data-action="history" data-id="${o.id}">Histórico e aceite</button></div></article>`).join(''):'<div class="empty"><h3>Nenhum recado nesta fila.</h3><p>Os novos envios do Hocco Message aparecem aqui.</p></div>'}</div></section><aside class="settings"><h3>Preço das duas posições</h3><p class="side-note">Todas começam em R$ 5,00. O reajuste vale só para os próximos pedidos.</p><form id="settings">${[1,2].map(i=>`<div class="field"><label for="price-${i}">Posição ${i} · R$</label><input id="price-${i}" name="price-${i}" type="number" step="0.01" min="5" max="9999" value="${s.prices[i-1]/100}" required></div>`).join('')}<div class="field"><label for="episode">Episódio em venda</label><input id="episode" name="episode" maxlength="70" value="${esc(s.episode)}" required></div><div class="field"><label for="publicationDeadline">Prazo para publicar</label><input id="publicationDeadline" name="publicationDeadline" type="datetime-local" value="${localDateTime(s.publication_deadline)}" required><small>Pedidos ficam indisponíveis quando a data passa.</small></div><div class="field"><label for="displayDurationSeconds">Tempo da mensagem na tela · segundos</label><input id="displayDurationSeconds" name="displayDurationSeconds" type="number" min="1" max="60" value="${s.display_duration_seconds||5}" required></div><div class="field"><label for="capacity">Vagas por posição no episódio</label><input id="capacity" name="capacity" type="number" min="1" max="200" value="${s.capacity_per_slot}" required></div><hr class="divider"><h3>Pagamento por PIX</h3><div class="field"><label for="pixKey">Chave PIX aleatória do banco</label><input id="pixKey" name="pixKey" autocomplete="off" value="${esc(s.pix_key)}" placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"></div><div class="field"><label for="paymentUrl">Link de pagamento</label><input id="paymentUrl" name="paymentUrl" type="url" value="${esc(s.payment_url)}" placeholder="https://…"></div><div class="field"><label for="payeeName">Nome do recebedor</label><input id="payeeName" name="payeeName" maxlength="100" value="${esc(s.payee_name)}"></div><div class="field"><label for="payeeCity">Cidade do recebedor</label><input id="payeeCity" name="payeeCity" maxlength="60" value="${esc(s.payee_city)}"></div><p class="side-note">Cadastre a chave realmente emitida pelo banco. Não há criação de chave bancária pelo aplicativo. Os dados do recebedor aparecem na área de pagamento do cliente.</p><button class="btn purple full" id="save-settings">Salvar configuração</button><div class="error" id="settings-error" role="alert"></div></form><hr class="divider"><button class="btn secondary full small" id="group-messages">Montar telas com dois recados</button><p class="side-note">Agrupa mensagens aprovadas e pagas em pares por episódio, com duas mensagens em cada tela.</p><a class="btn ghost small" href="/#termos" target="_blank" rel="noopener">Termos e políticas ↗</a></aside></div>`;$('#sponsor-tab').onclick=()=>{filter='sponsors';render()};$('#community-tab').onclick=()=>{filter='community';render()};$('#trash-tab').onclick=()=>{filter='trash';render()};$('#archive-all').onclick=async()=>{if(!confirm('Mover todos os pedidos e patrocínios atuais para a lixeira? O histórico será preservado e poderá ser restaurado.'))return;const b=$('#archive-all');b.disabled=true;try{const result=await call('admin.records.archive',{});filter='all';await load();toast((result.orders||0)+' pedidos e '+(result.sponsors||0)+' patrocínios arquivados.')}catch(e){b.disabled=false;toast(e.message)}};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.id,b.dataset.action));$('#group-messages').onclick=groupMessages;
$('#settings').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=$('#save-settings');b.disabled=true;try{await call('admin.settings',{payload:{prices:[1,2].map(i=>Math.round(Number(f.get('price-'+i))*100)).concat(s.prices.slice(2)),episode:f.get('episode').trim(),capacity:Number(f.get('capacity')),publicationDeadline:new Date(f.get('publicationDeadline')).toISOString(),displayDurationSeconds:Number(f.get('displayDurationSeconds')),pixKey:f.get('pixKey').trim(),paymentUrl:f.get('paymentUrl').trim(),payeeName:f.get('payeeName').trim(),payeeCity:f.get('payeeCity').trim(),bankName:''}});await load();toast('Configuração salva. Pedidos anteriores mantêm o preço.')}catch(e){if($('#settings-error'))$('#settings-error').textContent=e.message;b.disabled=false}}}
async function mutate(o,operation,payload={}){const result=await call('admin.mutate',{id:o.id,operation,payload});await load();toast(result.notificationError||'Pedido atualizado.')}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Texto copiado. Nenhum aviso foi enviado.')}catch{toast('Cópia indisponível. Selecione o texto manualmente.')}}
function act(id,action){const o=data.orders.find(x=>x.id===id);if(!o)return;
if(action==='approve'){mutate(o,action).catch(e=>toast(e.message));return}
if(action==='copy'){copy(`Posição ${o.slot}\n| ${o.message}\n${o.code}`);return}
if(action==='history'){const logs=data.audit.filter(x=>x.order_id===o.id).reverse(),labels={created:'Pedido recebido',approve:'Mensagem aprovada',reject:'Mensagem reprovada',pay:'Pagamento confirmado',refund:'Devolução registrada',publish:'Mensagem veiculada','payment-claimed':'Pagamento informado pelo cliente',reminder_sent:'Lembrete enviado',reminder_optout:'Lembretes cancelados'};modal(`<h2>Histórico e aceite</h2><p class="hint">${esc(o.code)}</p><div class="note">Versão: ${esc(o.acceptance.version)}<br>Aceite: ${esc(new Date(o.acceptance.acceptedAt).toLocaleString('pt-BR'))}<br>Maioridade declarada · exibição autorizada<br>WhatsApp: ${o.whatsapp_opt_in?'escolhido':'não escolhido'}</div><ol class="timeline">${logs.map(h=>`<li class="done">${esc(labels[h.action]||h.action)}<small>${esc(new Date(h.created_at).toLocaleString('pt-BR'))}</small></li>`).join('')}</ol>`);return}
if(action==='notice'){if(!o.whatsapp_opt_in||!o.phone)return;mutate(o,'notify').catch(e=>toast(e.message));return}
if(action==='reject'){modal(`<h2>Reprovar mensagem</h2><p class="subheading">Informe o motivo específico. Pagamentos confirmados entram na fila de devolução.</p><form><div class="field"><label for="reason">Motivo</label><textarea id="reason" name="reason" required maxlength="500"></textarea></div><div class="error" role="alert"></div><button class="btn danger full" type="submit">Confirmar reprovação</button></form>`,async(f,d)=>{await mutate(o,'reject',{reason:f.get('reason').trim()});d.close()});return}
if(action==='publish'){modal(`<h2>Publicar no YouTube</h2><p class="subheading">Esta mensagem foi aprovada e o pagamento foi confirmado. Registre o vídeo e o instante após conferir a inclusão.</p><form><div class="field"><label for="video">Link do vídeo</label><input id="video" type="url" name="url" required placeholder="https://www.youtube.com/watch?v=…"></div><div class="field"><label for="second">Instante em segundos</label><input id="second" type="number" name="second" min="0" max="86400" step="1" required></div><label class="check"><input type="checkbox" required><span>Conferi a exibição do texto aprovado.</span></label><div class="error" role="alert"></div><button class="btn full" type="submit">Confirmar veiculação</button></form>`,async(f,d)=>{await mutate(o,'publish',{url:f.get('url'),second:Number(f.get('second'))});d.close()});return}
if(['pay','refund'].includes(action)){const refund=action==='refund';modal(`<h2>${refund?'Registrar devolução':'Confirmar pagamento'}</h2><p class="subheading">Pedido ${esc(o.code)} · ${money(o.price_cents)}. Este registro não movimenta dinheiro. Confirme-o somente depois de conferir a transferência ou a devolução no extrato.</p><form><label class="check"><input type="checkbox" required><span>${refund?'Confirmei a devolução do valor ao cliente.':'Confirmei o recebimento no extrato bancário.'}</span></label><div class="error" role="alert"></div><button class="btn purple full" type="submit" style="margin-top:18px">Confirmar registro</button></form>`,async(_,d)=>{await mutate(o,action);d.close()})}}
function groupMessages(){const readyOrders=data.orders.filter(ready).slice().sort((a,b)=>a.created_at.localeCompare(b.created_at)),screens=[];for(const episode of [...new Set(readyOrders.map(o=>o.episode))]){const queue=readyOrders.filter(o=>o.episode===episode);for(let i=0;i<queue.length;i+=2)screens.push({episode,rows:queue.slice(i,i+2)})}const d=modal(`<h2>Telas para edição</h2><p class="subheading">Somente mensagens aprovadas e pagas. Cada tela reúne duas mensagens; os recados se alternam ao longo do episódio.</p>${screens.length?screens.map((s,i)=>`<div class="paper"><strong>Tela ${i+1} · ${esc(s.episode)}</strong>${s.rows.map((o,j)=>`<p class="hint">${j+1}. | ${esc(o.message)} <small>· ${esc(o.name)} · @${esc(o.social_handle||'')}</small></p>`).join('')}</div>`).join(''):'<div class="empty">Não há mensagens liberadas para a edição.</div>'}${screens.length?'<button class="btn purple full" id="copy-screens">Copiar roteiro das telas</button>':''}`);d.querySelector('#copy-screens')?.addEventListener('click',()=>copy(screens.map((s,i)=>`TELA ${i+1} — ${s.episode}\n`+s.rows.map((o,j)=>`${j+1}. | ${o.message} (@${o.social_handle||''})`).join('\n')).join('\n\n')))}
load();
